import{_ as t,c as a,o,a3 as i}from"./chunks/framework.Dokpd4od.js";const x=JSON.parse('{"title":"Taxes","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/taxes/index.md","filePath":"master/finance/taxes/index.md","lastUpdated":1792041590000}'),s={name:"master/finance/taxes/index.md"};function n(r,e,l,c,d,h){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="taxes" tabindex="-1">Taxes <a class="header-anchor" href="#taxes" aria-label="Permalink to &quot;Taxes&quot;">​</a></h1><p>Taxes are the percentages or fixed amounts you add to what you sell and buy, such as sales tax or VAT. In Aureus ERP you define each tax once. You then attach it to products, and it is calculated for you on every invoice and bill line and posted to the right accounts.</p><blockquote><p><strong>In simple words:</strong> Create the tax once, attach it to a product, and Aureus adds it to every invoice line for you.</p></blockquote><h2 id="what-is-in-this-group" tabindex="-1">What is in this group <a class="header-anchor" href="#what-is-in-this-group" aria-label="Permalink to &quot;What is in this group&quot;">​</a></h2><ul><li><a href="./taxes.html">Taxes</a>: create and manage taxes, including percentage, fixed, group and formula taxes.</li><li><a href="./tax-groups.html">Tax groups</a>: the headings under which taxes are shown together.</li><li><a href="./fiscal-positions.html">Fiscal positions</a>: rules per customer type or region. Accounting app only.</li><li><a href="./tax-settings.html">Tax settings</a>: default taxes, rounding, and whether prices include tax. Accounting app only.</li></ul><h2 id="where-to-find-taxes" tabindex="-1">Where to find taxes <a class="header-anchor" href="#where-to-find-taxes" aria-label="Permalink to &quot;Where to find taxes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Invoices app</th><th>Accounting app</th></tr></thead><tbody><tr><td>Taxes</td><td><code>Invoices → Configurations → Taxes</code></td><td><code>Accounting → Configurations → Accounting → Taxes</code></td></tr><tr><td>Tax Groups</td><td><code>Invoices → Configurations → Tax Groups</code></td><td><code>Accounting → Configurations → Accounting → Tax Groups</code></td></tr><tr><td>Fiscal Positions</td><td>-</td><td><code>Accounting → Configurations → Accounting → Fiscal Positions</code></td></tr><tr><td>Manage Taxes</td><td>-</td><td><code>Accounting → Settings → Manage Taxes</code></td></tr></tbody></table><h2 id="set-up-in-this-order" tabindex="-1">Set up in this order <a class="header-anchor" href="#set-up-in-this-order" aria-label="Permalink to &quot;Set up in this order&quot;">​</a></h2><ol><li>Run <a href="./../get-started/accounting-setup.html">Set up accounting</a>. It creates a first sales tax and purchase tax of 15 % in the sample set-up.</li><li>Review the <strong>Prices</strong> setting in <a href="./tax-settings.html">Tax settings</a> before you create your first invoice. It is locked after that.</li><li>Create or adjust your <a href="./tax-groups.html">Tax groups</a>.</li><li>Create your <a href="./taxes.html">Taxes</a>. Make one for Sale and one for Purchase for each rate.</li><li>Add the taxes to your products. See <a href="./../../sales/sales/products-prices/manage-products.html">Manage products</a>.</li><li>If you serve customers in different regions, add <a href="./fiscal-positions.html">Fiscal positions</a>.</li></ol><h2 id="how-taxes-reach-an-invoice" tabindex="-1">How taxes reach an invoice <a class="header-anchor" href="#how-taxes-reach-an-invoice" aria-label="Permalink to &quot;How taxes reach an invoice&quot;">​</a></h2><ol><li>A product has <strong>Customer Taxes</strong> for sales and vendor taxes for purchases.</li><li>When you add the product to an invoice line, those taxes fill the <strong>Taxes</strong> field of the line.</li><li>Aureus calculates the tax and shows it in the invoice totals.</li><li>When you confirm the invoice, the tax amount is posted to the account set on the tax.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can change the <strong>Taxes</strong> field on a single line, for example to remove the tax for one exempt item.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li><li><a href="./../vendor-bills/create-bill.html">Create a vendor bill</a></li><li><a href="./../get-started/chart-of-accounts.html">Chart of accounts</a></li><li><a href="./../">Finance overview</a></li></ul>',14)]))}const p=t(s,[["render",n]]);export{x as __pageData,p as default};
